<x-result.layout :title="$display['name']" :noindex="$preview ?? false">
    @if($preview ?? false)<div class="rr-preview"><strong>{{ __('result.preview_title') }}</strong><span>{{ __('result.preview_hint') }}</span></div>@endif
    <a class="rr-back" href="{{ ($preview ?? false) ? route('eys.competitions.show', $competition) : route('result.index') }}">← {{ ($preview ?? false) ? __('result.back_to_eys') : __('result.back') }}</a>
    <header class="rr-hero"><div class="rr-kicker">{{ $display['institution'] }}</div><h1 class="rr-title">{{ $display['name'] }}</h1><p class="rr-lead">{{ $display['subject'] }}</p><div class="rr-stats"><div class="rr-stat"><strong>{{ $display['category_count'] }}</strong>{{ __('result.categories') }}</div><div class="rr-stat"><strong>{{ ($display['participant_count'] ?? '—') }}</strong>{{ __('result.participants') }}</div><div class="rr-stat"><strong>{{ ($display['photo_count'] ?? '—') }}</strong>{{ __('result.photos') }}</div></div></header>
    @if($display['partial'])<p role="status">{{ __('result.archive_partial') }}</p>@endif
    <nav class="rr-tabs" aria-label="{{ __('result.result_sections') }}"><a href="#results">{{ __('result.results') }}</a><a href="#information">{{ __('result.information') }}</a><a href="#participants">{{ __('result.awarded_participants') }}</a><a href="#statistics">{{ __('result.statistics') }}</a></nav>
    <section id="results" class="rr-section"><h2>{{ __('result.results') }}</h2>
        @if($display['awarded_count'] === 0)<div class="rr-empty">{{ __('result.no_awards') }}</div>@endif
        @foreach($display['categories'] as $category)
            @php $categoryResults = $display['results']->get($category['id'], collect())->sortBy('rank'); @endphp
            @if($categoryResults->isNotEmpty())<h3>{{ $category['name'] }}</h3><div class="rr-gallery">@foreach($categoryResults as $result)<article class="rr-work"><div x-data="{ failed: false }">@if($result['photo_url'])<img src="{{ $result['photo_url'] }}" alt="{{ __('result.awarded_photo_alt', ['category' => $category['name']]) }}" loading="lazy" x-show="!failed" x-on:error="failed = true"><p x-show="failed" x-cloak>{{ __('result.image_unavailable') }}</p>@else<p>{{ __('result.image_unavailable') }}</p>@endif</div><div class="rr-work-body"><div class="rr-award">{{ $result['awards_text'] }}</div><h3>{{ $result['participant'] }}</h3>@if($result['series_code'] ?? null)<p>{{ __('series.identity', ['code' => $result['series_code']]) }}</p>@endif<p>#{{ $result['rank'] }} · {{ $category['name'] }}</p></div></article>@endforeach</div>@endif
        @endforeach
    </section>
    <section id="information" class="rr-section"><h2>{{ __('result.information') }}</h2><div class="rr-table-wrap"><table class="rr-table"><tbody><tr><th>{{ __('result.institution') }}</th><td>{{ $display['institution'] }}</td></tr><tr><th>{{ __('result.type') }}</th><td>{{ $display['type'] }}</td></tr><tr><th>{{ __('result.result_date') }}</th><td>{{ $display['published_at']?->format('d.m.Y H:i') ?: __('result.not_published_yet') }}</td></tr><tr><th>{{ __('result.publication_version') }}</th><td>v{{ $display['version'] ?? '—' }}</td></tr><tr><th>{{ __('result.evaluation_round') }}</th><td>{{ $display['round'] }}</td></tr></tbody></table></div></section>
    @if(!($preview ?? false) && isset($publicationHistory) && $publicationHistory->isNotEmpty())
        <section class="rr-section" id="publication-history"><h2>{{ __('result.publication_history') }}</h2><div class="rr-table-wrap"><table class="rr-table"><thead><tr><th>{{ __('result.publication_version') }}</th><th>{{ __('result.result_date') }}</th><th>{{ __('result.publication_note') }}</th><th>{{ __('result.correction_note') }}</th></tr></thead><tbody>@foreach($publicationHistory as $publication)<tr><td>v{{ $publication->version }}</td><td>{{ $publication->published_at->format('d.m.Y H:i') }}</td><td>{{ $publication->publication_note ?: '—' }}</td><td>{{ $publication->correction_note ?: '—' }}</td></tr>@endforeach</tbody></table></div></section>
    @endif
    <section id="participants" class="rr-section"><h2>{{ __('result.awarded_participants') }}</h2><div class="rr-table-wrap"><table class="rr-table"><thead><tr><th>{{ __('result.participant') }}</th></tr></thead><tbody>@foreach($display['participants'] as $participant)<tr><td>{{ $participant }}</td></tr>@endforeach</tbody></table></div></section>
    <section id="statistics" class="rr-section"><h2>{{ __('result.statistics') }}</h2><div class="rr-stats"><div class="rr-stat"><strong>{{ ($display['participant_count'] ?? '—') }}</strong>{{ __('result.total_participants') }}</div><div class="rr-stat"><strong>{{ ($display['photo_count'] ?? '—') }}</strong>{{ __('result.total_photos') }}</div><div class="rr-stat"><strong>{{ $display['results']->flatten(1)->count() }}</strong>{{ __('result.awarded_works') }}</div></div></section>
</x-result.layout>
